station_modules = [['Oxygen', 'Water'], ['Solar', 'Radar'], ['Engine', 'Nav']]
system_codes = [['NOMINAL', 'FAULTY'], ['NOMINAL', 'NOMINAL']]

# Task 1: Print grid coordinates
for row in range(3):
    for col in range(4):
        print(row, col)

# Task 2: Print all equipment
for module in station_modules:
    for item in module:
        print(item)

# Task 3: Emergency scan with break
for module in system_codes:
    for code in module:
        print(code)
        if code == 'FAULTY':
            break
